create or replace TABLE KFL_PRODUCTION.DBP_DATA.WUP_1 (
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	VW_ID NUMBER(38,0) DEFAULT 0 COMMENT 'ID des Vertriebsweges. Einkaufs-Sicht auf die wup_1 Objekte (Restaurants und Backshops z.Bsp. haben keinen Vertriebsweg)',
	VS_ID NUMBER(38,0) DEFAULT 0 COMMENT 'ID der Vertriebsschiene. Vertriebs-Sicht auf die wup_1 Objekte',
	LAND_ID VARCHAR(8) NOT NULL COLLATE 'en-ci' DEFAULT '  ' COMMENT 'Land_1, in dem sich der Markt befindet (PL, CZ, DE,..)',
	REGION_ID NUMBER(38,0) COMMENT 'Bundesland, in dem sich der Markt befindet',
	DAT_VON DATE COMMENT 'Eröffnungsdatum. Muss nicht der 1. Abverkaufstag sein! Format YYYY-MM_1-DD',
	WUP_TYP_ID NUMBER(38,0) DEFAULT 0 COMMENT 'entspricht der Kennzeichnung der Art_1 des Umschlagplatzes (0: normaler Markt; 1: Lager; 2: Verteilzentrum : -1 System. Neu könnten hier auch noch Mitbewerbermärkte geführt werden.',
	WUP_NAME_V VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Marktbezeichnung für den Vertrieb (aus Hyperion gepflegt)',
	WUP_NAME_E VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Marktbezeichnung für den Einkauf (aus SAP gepflegt)',
	WUP_STANDORT VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Ortsbezeichnung',
	WUP_PLZ VARCHAR(40) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Postleitzahl',
	WUP_STR VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Strasse',
	VF_ID NUMBER(38,0) DEFAULT 0 COMMENT 'Vertriebsform (Kaufland, Handelshof,...)',
	VKL_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Verkaufsleiter - kommt aus der Hyperion - Schnittstelle',
	HL_ID NUMBER(38,0) COMMENT 'Hausleiter',
	DAT_BIS DATE DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Schließungsdatum Format ''YYYY-MM_1-DD''',
	LEAD_MWST NUMBER(9,3) COMMENT 'Mehrwertsteuersatz - ID (<> Mehrwertsteuersatz!)',
	UEBERNAHME_VON VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'von welchem Mitbewerber wurde der Markt übernommen',
	BREAKEVENUMSATZ NUMBER(18,2) DEFAULT 0 COMMENT 'Kennzahl, kommt aus Hyperion',
	SYSTEMRENTABILITAET NUMBER(18,2) DEFAULT 0 COMMENT 'Kennzahl, kommt aus Hyperion',
	VERKAUFSFLAECHE NUMBER(18,2) DEFAULT 0 COMMENT 'Verkaufsfläche des Marktes',
	BETRIEBSFLAECHE NUMBER(18,2) DEFAULT 0 COMMENT 'Betriebsfläche des Marktes',
	FLEISCHSYSTEM NUMBER(38,0) DEFAULT 0 COMMENT 'Kennzeichnung, ob Fleischtheke vorhanden. Wird z.Zt nicht benutzt',
	PREISKATEGORIE_FOOD NUMBER(38,0) COMMENT 'Preiskategorie Food für den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	PREISKATEGORIE_NONFOOD NUMBER(38,0) COMMENT 'Preiskategorie Nonfood für den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	SORTKATEGORIE_FOOD NUMBER(38,0) COMMENT 'Sortimentskategorie Food für den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe',
	SORTKATEGORIE_NONFOOD NUMBER(38,0) COMMENT 'Preiskategorie Nonfood für den Markt (wird in TP1 benutzt) In TP2 erfolgt die Zuordnung auf Ebene Markt/Warengruppe. Ist z.Zt. immer mit Null gefüllt',
	SONDERMARKT NUMBER(38,0) COMMENT 'wird z.Zt. nicht benutzt',
	REF_WUP_ID NUMBER(38,0) DEFAULT 0 COMMENT 'wird z.Zt. nicht benutzt',
	WM_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Warenmanager ID',
	KASSENTYP VARCHAR(40) DEFAULT '          ' COMMENT 'im Markt benutztes Kassensystem (aus ods_bon_transaction.kassensystem_name)',
	DAT_QBM_UMSTELLUNG DATE COMMENT 'Datum seit wann QBM (oder die aktuelle QBM-Version) im Markt aktiv ist',
	GETRAENKEMARKT_FG NUMBER(38,0) DEFAULT 0 COMMENT 'Getränkemarkt Flag',
	KUNDENFAKTOR NUMBER(11,10) DEFAULT 1 COMMENT 'Korrekturfaktor zur Ermittlung der Anzahl der Kunden, bei Märkten mit Getränkemarkt angewendet',
	VZ_WUP_ID NUMBER(38,0) COMMENT 'Beim wup_1 vom Typ \"Lager\" ist hier das Verteilzentrum eingetragen',
	QBM_ID NUMBER(38,0) COMMENT 'Kennzeichnung, ob der Markt über ein QBM-System verfügt (Reklamationsabwicklung)',
	WUP_ID_ALT NUMBER(38,0) COMMENT 'Bei Wechsel der Marktnummer wird hier die alte Marktnummer hinterlegt',
	VERKAUFSORGANISATION_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Organisatorische Einheit, die für den Vertrieb bestimmter Produkte oder Dienstleistungen verantwortlich ist, z. B. KL = Kaufland.',
	BUCHUNGSKREIS_ID NUMBER(38,0) COMMENT 'Zuordnung des Buchungskreises zu dem WUP_1 über die SAP Quelle T001K und T001. Der Buchungskreis entspricht unter dem Mandanten einer Zusammenfassung von Werken (Hierarchie: Mandant_1, Buchungskreis, Werk/Betrieb). Bsp: Buchungskreis 282 entspricht Kaufland WH Oranienburg GmbH',
	DAT_EROEFFNUNG DATE COMMENT '\"Echtes\" Eröffnungsdatum des Marktes. Kann von dat_von abweichen.',
	BEWERTUNGSKREIS_ID VARCHAR(16) COLLATE 'en-ci' DEFAULT '    ' COMMENT 'der Bewertungskreis enthält die wup_id. Theoretisch kann auch ein Buchungskreis enthalten sein. Über den Bewertungskreis wird die Verbindung zum Gleitenden Durchschnittspreis hergestellt',
	WUP_STADT VARCHAR(160) COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Ort aus der Adresse des Marktes',
	HAUPT_WUP_ID NUMBER(38,0) COMMENT 'Hier ist der uebergeordnete wup_1 gespeichert, falls mehrere wup_ids logisch zusammengehoeren (z.Bsp. Restaurant zu Markt)',
	KREISTYP_GRUPPE_ID VARCHAR(16) COLLATE 'en-ci' COMMENT 'Region_1 / Gruppierung Kreistypen',
	DAT_UMSTELLUNG_WAAGE DATE NOT NULL DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Datum, ab dem die Waagendaten sich im DWH befinden. Default ist der 31.12.9999',
	DAT_VON_ALT DATE COMMENT 'Nur bei Umzugsfilialen gefüllt: Das dat_von der Vorgänger-Filiale',
	DAT_EROEFFNUNG_ALT DATE COMMENT 'Nur bei Umzugsfilialen gefüllt: Das Eröffnungsdatum der Vorgänger-Filiale',
	UMZUGSFILIALE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Ist = 1 bei geschlossenen Filialen, für die eine_1 Nachfolger-Filiale existiert. Sonst = 0',
	WUP_AENDERUNG_GRUND_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Numerischer Code fuer den Grund der WUP_1 ID Aenderung. Ist gefuellt fuer die wup_id, die die Aenderung erfahren hat, somit bei der aktuellen wup_id standardmaessig 0. Der Aenderungsgrund steht immer in der alten wup_1 ID.\n            Moegliche Auspraegungen:\n            0 = keine Aenderung\n            1 = Umzug (Historie / vor Einfuehrung der Filialumgliederungen)\n            2 = Umzug (seit Einfuehrung der Filialumgliederungen)\n            3 = Umgliederung\n            4 = Abriss / Neubau',
	GF_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Geschäftsführer ID, numerisch. Wird hierzur Performancesteigerung denormalisiert abgelegt, um den Join zur VKL_1-Tabelle zu ersparen',
	UMSATZ_EA_EUR NUMBER(18,2) DEFAULT 0 COMMENT 'Umsatz laut Expansionsauftrag pro Jahr in Euro - Wert wird manuell gepflegt, da keinne SST zur Expansionsdatenbank besteht',
	UMSATZ_EA_LAND NUMBER(18,2) DEFAULT 0 COMMENT 'Umsatz laut Expansionsauftrag pro Jahr in Landeswährung - Wert wird manuell gepflegt, da keinne SST zur Expansionsdatenbank besteht. Umrechnung über Kurstabelle vom Anwender nicht erwünscht.',
	BREITENGRAD NUMBER(38,16) COMMENT 'Breitengrad aus dem GIS-System (Latitude)',
	LAENGENGRAD NUMBER(38,16) COMMENT 'Längengrad aus dem GIS-System (Longitude)',
	GIS_QUALI_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Numerische ID des GIS Qualitätskennzeichens. ',
	GLN_ID VARCHAR(80) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Global Location_1 Number - international  eindeutige Kennzeichnung der Lokation. Quelle ist KNA1_1 (Retail) mit den Feldern bbbnr(Basisnummer), bbsnr(Individueller Nummernteil) und bubkz(Prüfziffer)',
	FIPO_PRUEF_OBJEKT_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'eindeutige ID eines Prüfobjekts aus dem Quellfeld pob_id',
	ADRESSE_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Adressnummer aus dem Quellfeld adrnr. Referenz zur SAP Tabelle adrc_1 (im DWH nicht vorhanden)',
	DAT_DAYFORCE_AB DATE NOT NULL DEFAULT CAST('9999-12-31' AS DATE) COMMENT 'Datum, ab dem die Personaldaten aus',
	MANDANT_ID_URSPRUNG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'ursprüngliche Mandant_1 ID DWH bezüglich des Liefersystem (SAP) - Bsp. Moldau wird im SAP-System Rumänien verwaltet, deshalb wird in diesem Feld die Mandant_1 ID von Rumänien gespeichert',
	EIGENTUM_MIETE_KZ VARCHAR(4) COLLATE 'en-ci' COMMENT 'Kennzeichen, ob es sich bei der Filiale um Eigentum (=E) oder Mietobjekt (=M) handelt (kann auch null sein, wenn nicht definiert)',
	DAT_LETZTE_MODERNISIERUNG_VON DATE COMMENT 'Datum Start letzte Modernisierungsmaßnahme (Format JJJJ-MM_1-TT)',
	DAT_LETZTE_MODERNISIERUNG_BIS DATE COMMENT 'Datum Ende letzte Modernisierungsmaßnahme (Format JJJJ-MM_1-TT)',
	DAT_LETZTER_FACELIFT DATE COMMENT 'Datum Start letzter Facelift (Format JJJJ-MM_1-TT)',
	DAT_WIEDEREROEFFNUNG DATE COMMENT 'Datum der Wiedereröffnung bei Abriss/Neubau, bei denen die Marktnummer gleich bleibt (Datum wird manuell gepflegt, da keine Quelle)',
	EINWOHNER_ANZAHL NUMBER(38,0) COMMENT 'Einwohner je Markt. Manuelle Befüllung',
	UMSATZ_ERWARTUNG_EUR NUMBER(18,2) COMMENT 'Umsatz Erwartung je Markt. Manuelle Befüllung',
	DAT_LETZTER__FACELIFT_VON DATE COMMENT 'Datum des letzten Facelifts des Marktes. Manuelle Befüllung',
	FILIALTYP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Filialtypisierung für Sortimentskonzept. (VT Orga INT). Wird jaehrlich manuell aktualisiert.',
	ETAGEN_ANZ NUMBER(38,0) NOT NULL DEFAULT 1 COMMENT 'Anzahl der Etagen, Aktuell liegt diese Information nur für Filialen vor (nb_id = 0). Der Standardwert gilt nur für Filialen. (manuell gepflegt)',
	ORIG_WUP_ID NUMBER(38,0) COMMENT 'Originale / urspruengliche WUP_1 ID dieser Filiale.',
	AKTUELL_WUP_ID NUMBER(38,0) COMMENT 'Aktuelle WUP_1 ID dieser Filiale.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_WUP primary key (WUP_ID, NB_ID, MANDANT_ID)
)COMMENT='VIS TP2  - Warenumschlagsplatz. Enthält Maerkte, Restaurants, Tankstellen, Laeger und Verteilzentren'
;